import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.C0KMm31j.js";const p="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_cover.png",o="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_01_system_architecture.png",i="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_02_lifecycle_threads.png",l="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_03_sensor_obstacle.png",r="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_04_update_fusion.png",c="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_05_footprint_inflation.png",d="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_06_outputs_services.png",y=JSON.parse('{"title":"一束激光怎样变成避障代价？拆解 nav2_costmap_2d 调用全数据流","description":"地图告诉机器人哪里有墙，激光雷达告诉机器人眼前出现了什么，Footprint 告诉系统机器人到底有多大。","frontmatter":{"title":"一束激光怎样变成避障代价？拆解 `nav2_costmap_2d` 调用全数据流","description":"地图告诉机器人哪里有墙，激光雷达告诉机器人眼前出现了什么，Footprint 告诉系统机器人到底有多大。","date":"2026-07-15","topic":"Nav2 工程实践","section":"四 · 代价地图与安全","readingTime":14,"source":"2026-07-15/nav2_costmap_2d_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-15/nav2_costmap_2d_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-costmap-2d-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一束激光怎样变成避障代价？拆解 `nav2_costmap_2d` 调用全数据流"}],["meta",{"property":"og:description","content":"地图告诉机器人哪里有墙，激光雷达告诉机器人眼前出现了什么，Footprint 告诉系统机器人到底有多大。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-costmap-2d-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-15"}],["meta",{"name":"twitter:title","content":"一束激光怎样变成避障代价？拆解 `nav2_costmap_2d` 调用全数据流"}],["meta",{"name":"twitter:description","content":"地图告诉机器人哪里有墙，激光雷达告诉机器人眼前出现了什么，Footprint 告诉系统机器人到底有多大。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_costmap_2d_cover.png"}]],"prev":{"text":"机器人明明在动，却被 Nav2 判定“卡住”？拆解 5 个进展与到点检查器","link":"/nav2/nav2-controller-checkers-source-walkthrough"},"next":{"text":"一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d","link":"/nav2/nav2-costmap-2d-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-costmap-2d-full-dataflow.md","filePath":"nav2/nav2-costmap-2d-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-costmap-2d-full-dataflow.md"};function u(m,a,b,_,g,v){return s(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="一束激光怎样变成避障代价-拆解-nav2-costmap-2d-调用全数据流" tabindex="-1">一束激光怎样变成避障代价？拆解 <code>nav2_costmap_2d</code> 调用全数据流 <a class="header-anchor" href="#一束激光怎样变成避障代价-拆解-nav2-costmap-2d-调用全数据流" aria-label="Permalink to &quot;一束激光怎样变成避障代价？拆解 `nav2_costmap_2d` 调用全数据流&quot;">​</a></h1><p><img src="'+p+'" alt="封面：Nav2 的安全边界"></p><p>地图告诉机器人哪里有墙，激光雷达告诉机器人眼前出现了什么，Footprint 告诉系统机器人到底有多大。</p><p>但 Planner 和 Controller 最终不能直接拿着这三份数据做决策。它们需要一张统一的二维栅格：每个格子都用一个代价值表达“从这里通过有多危险”。</p><p>这张图就是 Costmap。</p><p><code>nav2_costmap_2d</code> 不只是“把障碍物画进地图”。它同时处理 Lifecycle、TF、静态地图、LaserScan、PointCloud2、机器人几何、滚动窗口、多插件融合、膨胀、安全区、过滤器、增量发布、清图服务和碰撞检查。</p><p>本文从一帧 <code>/scan</code> 出发，完整追踪它怎样进入 ObservationBuffer，怎样标记和清除栅格，怎样与静态层融合，再怎样经过 Inflation Layer 变成 Planner 和 Controller 使用的安全代价。</p><p><img src="'+o+`" alt="图 1：nav2_costmap_2d 系统调用总览"></p><h2 id="一、先给结论-costmap-是-环境数据融合器-不是地图副本" tabindex="-1">一、先给结论：Costmap 是“环境数据融合器”，不是地图副本 <a class="header-anchor" href="#一、先给结论-costmap-是-环境数据融合器-不是地图副本" aria-label="Permalink to &quot;一、先给结论：Costmap 是“环境数据融合器”，不是地图副本&quot;">​</a></h2><p>静态地图通常只有 free、occupied 和 unknown。Costmap 内部却使用 0～255 的 unsigned char 代价值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0    FREE_SPACE</span></span>
<span class="line"><span>1～252 渐变代价</span></span>
<span class="line"><span>253  INSCRIBED_INFLATED_OBSTACLE</span></span>
<span class="line"><span>254  LETHAL_OBSTACLE</span></span>
<span class="line"><span>255  NO_INFORMATION</span></span></code></pre></div><p>它融合的输入至少包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/map                     静态 OccupancyGrid</span></span>
<span class="line"><span>LaserScan／PointCloud2    动态障碍观测</span></span>
<span class="line"><span>Range                    距离传感器观测</span></span>
<span class="line"><span>TF                       机器人和传感器坐标转换</span></span>
<span class="line"><span>robot_radius／footprint   机器人几何</span></span>
<span class="line"><span>Costmap Filter mask/info 禁行区、限速区等语义约束</span></span></code></pre></div><p>输出则流向：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Planner Server     评估全局路径是否穿过高代价区域</span></span>
<span class="line"><span>Controller Server  评估局部轨迹、速度和碰撞风险</span></span>
<span class="line"><span>Behavior Server    预测恢复动作是否会碰撞</span></span>
<span class="line"><span>RViz2／工具节点     显示、查询和调试代价地图</span></span></code></pre></div><p>所以 Costmap 不是 Map Server 的复制品，而是随机器人、传感器和插件状态不断变化的导航风险场。</p><h2 id="二、一个-costmap-由三层对象组成" tabindex="-1">二、一个 Costmap 由三层对象组成 <a class="header-anchor" href="#二、一个-costmap-由三层对象组成" aria-label="Permalink to &quot;二、一个 Costmap 由三层对象组成&quot;">​</a></h2><h3 id="_2-1-costmap2dros-ros-与-lifecycle-外壳" tabindex="-1">2.1 Costmap2DROS：ROS 与 Lifecycle 外壳 <a class="header-anchor" href="#_2-1-costmap2dros-ros-与-lifecycle-外壳" aria-label="Permalink to &quot;2.1 Costmap2DROS：ROS 与 Lifecycle 外壳&quot;">​</a></h3><p><code>Costmap2DROS</code> 负责：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取参数</span></span>
<span class="line"><span>创建 TF Buffer</span></span>
<span class="line"><span>动态加载插件和 Filter</span></span>
<span class="line"><span>管理 Lifecycle</span></span>
<span class="line"><span>启动更新线程</span></span>
<span class="line"><span>创建发布器、Footprint 接口和清图服务</span></span></code></pre></div><p>它本身不实现静态地图、障碍物或膨胀算法。</p><h3 id="_2-2-layeredcostmap-融合调度器" tabindex="-1">2.2 LayeredCostmap：融合调度器 <a class="header-anchor" href="#_2-2-layeredcostmap-融合调度器" aria-label="Permalink to &quot;2.2 LayeredCostmap：融合调度器&quot;">​</a></h3><p><code>LayeredCostmap</code> 保存两个或一个主栅格，以及有序插件列表：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins_  Static／Obstacle／Voxel／Inflation／Denoise 等</span></span>
<span class="line"><span>filters_  Keepout／Speed／Binary 等后处理层</span></span></code></pre></div><p>每轮更新由它计算更新窗口，再按配置顺序调用各层。</p><h3 id="_2-3-costmap2d-真正的二维数组" tabindex="-1">2.3 Costmap2D：真正的二维数组 <a class="header-anchor" href="#_2-3-costmap2d-真正的二维数组" aria-label="Permalink to &quot;2.3 Costmap2D：真正的二维数组&quot;">​</a></h3><p><code>Costmap2D</code> 保存：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>size_x／size_y</span></span>
<span class="line"><span>resolution</span></span>
<span class="line"><span>origin_x／origin_y</span></span>
<span class="line"><span>unsigned char costmap_[]</span></span>
<span class="line"><span>mutex</span></span></code></pre></div><p>它提供 worldToMap、mapToWorld、resizeMap、updateOrigin、resetMap、raytraceLine、copyWindow 等底层操作。</p><h2 id="三、lifecycle-与两类线程怎样配合" tabindex="-1">三、Lifecycle 与两类线程怎样配合 <a class="header-anchor" href="#三、lifecycle-与两类线程怎样配合" aria-label="Permalink to &quot;三、Lifecycle 与两类线程怎样配合&quot;">​</a></h2><p>Costmap 通常以内嵌节点形式存在于 Planner Server 或 Controller Server 中，但它自己仍是 LifecycleNode。</p><p><img src="`+i+`" alt="图 2：Costmap2DROS Lifecycle 与线程模型"></p><h3 id="_3-1-configure-搭好全部数据通道" tabindex="-1">3.1 CONFIGURE：搭好全部数据通道 <a class="header-anchor" href="#_3-1-configure-搭好全部数据通道" aria-label="Permalink to &quot;3.1 CONFIGURE：搭好全部数据通道&quot;">​</a></h3><p>configure 阶段读取：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global_frame／robot_base_frame</span></span>
<span class="line"><span>width／height／resolution／origin</span></span>
<span class="line"><span>rolling_window／track_unknown_space</span></span>
<span class="line"><span>update_frequency／publish_frequency</span></span>
<span class="line"><span>plugins／filters</span></span>
<span class="line"><span>robot_radius／footprint／footprint_padding</span></span></code></pre></div><p>随后创建 <code>LayeredCostmap</code>，按米制尺寸和分辨率分配栅格；创建 TF Buffer 和 Listener；通过 pluginlib 依次加载 Layer 与 Filter。</p><p>默认插件为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static_layer</span></span>
<span class="line"><span>obstacle_layer</span></span>
<span class="line"><span>inflation_layer</span></span></code></pre></div><p>插件顺序不是展示顺序，而是写入 Master Costmap 的执行顺序。通常静态和动态障碍层先写，Inflation 最后根据已存在的致命障碍生成安全梯度。</p><p>configure 还创建：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>footprint 订阅</span></span>
<span class="line"><span>published_footprint 发布</span></span>
<span class="line"><span>Costmap2DPublisher</span></span>
<span class="line"><span>三类 Clear Costmap 服务</span></span></code></pre></div><p>ROS 回调被放入一个 <code>MutuallyExclusive</code> callback group，并交给独立的 <code>SingleThreadedExecutor + NodeThread</code>。</p><h3 id="_3-2-activate-先等-tf-再跑更新循环" tabindex="-1">3.2 ACTIVATE：先等 TF，再跑更新循环 <a class="header-anchor" href="#_3-2-activate-先等-tf-再跑更新循环" aria-label="Permalink to &quot;3.2 ACTIVATE：先等 TF，再跑更新循环&quot;">​</a></h3><p>activate 先激活 Costmap 和 Footprint Publisher，然后循环等待：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global_frame ← robot_base_frame</span></span></code></pre></div><p>没有这个 TF，系统无法知道机器人位于哪个栅格，也无法建立滚动窗口中心。当前实现会持续等待并周期打印错误，而不是带着未知位姿开始更新。</p><p>TF 可用后创建独立 <code>map_update_thread</code>，以 <code>update_frequency</code> 调用 <code>updateMap()</code>，再激活全部插件和 Filter 的订阅。</p><p>因此存在两类执行上下文：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>callback executor thread  处理 TF、传感器、地图、Footprint、服务等回调</span></span>
<span class="line"><span>map update thread         周期读取最新缓存并融合 Costmap</span></span></code></pre></div><p>两者通过各层和 Master Costmap 的 mutex 保证一致性。</p><h3 id="_3-3-更新频率不等于发布频率" tabindex="-1">3.3 更新频率不等于发布频率 <a class="header-anchor" href="#_3-3-更新频率不等于发布频率" aria-label="Permalink to &quot;3.3 更新频率不等于发布频率&quot;">​</a></h3><p><code>update_frequency</code> 决定内部融合多久执行一次；<code>publish_frequency</code> 决定多快把结果发给外部订阅者。</p><p>Planner 和 Controller 在同一进程内通常直接读取 Master Costmap，因此即使发布频率较低，它们也能看到更高更新频率的内部结果。</p><p><code>update_frequency=0</code> 会直接禁用更新循环。<code>publish_frequency≤0</code> 则禁用周期发布，两者含义不同。</p><h2 id="四、静态地图怎样进入-staticlayer" tabindex="-1">四、静态地图怎样进入 StaticLayer <a class="header-anchor" href="#四、静态地图怎样进入-staticlayer" aria-label="Permalink to &quot;四、静态地图怎样进入 StaticLayer&quot;">​</a></h2><p>StaticLayer 订阅配置的 <code>map_topic</code>。默认支持 transient local、reliable、KeepLast(1)，因此可以收到 Map Server 早先发布的最近地图。</p><p>收到 OccupancyGrid 后，StaticLayer 先检查宽、高、分辨率和原点。</p><p>对于非滚动 Global Costmap，如果 Master 尺寸不匹配，且尺寸未被锁定，StaticLayer 会调用 <code>LayeredCostmap::resizeMap()</code>，让整个 Layered Costmap 与静态地图一致。</p><p>每个 OccupancyGrid 值再由 <code>interpretValue()</code> 转成内部代价，受这些参数影响：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>track_unknown_space</span></span>
<span class="line"><span>unknown_cost_value</span></span>
<span class="line"><span>lethal_cost_threshold</span></span>
<span class="line"><span>trinary_costmap</span></span></code></pre></div><p>静态层可以 true overwrite 或 maximum 方式合入 Master。滚动窗口下，如果 StaticLayer 的地图 frame 与 Costmap global frame 不同，还要通过 TF 逐栅格转换。</p><p>所以 <code>/map</code> 显示正常，不代表 StaticLayer 必然正常：QoS、frame、尺寸锁定和阈值解释都可能阻断或改变静态代价链。</p><h2 id="五、一帧-laserscan-怎样变成障碍物" tabindex="-1">五、一帧 LaserScan 怎样变成障碍物 <a class="header-anchor" href="#五、一帧-laserscan-怎样变成障碍物" aria-label="Permalink to &quot;五、一帧 LaserScan 怎样变成障碍物&quot;">​</a></h2><p>ObstacleLayer 的 <code>observation_sources</code> 可以配置多个来源。当前支持 LaserScan 和 PointCloud2；Range 由独立 RangeSensorLayer 处理。</p><p><img src="`+l+`" alt="图 3：动态障碍的标记与清除链"></p><h3 id="_5-1-messagefilter-先保证-tf-可用" tabindex="-1">5.1 MessageFilter 先保证 TF 可用 <a class="header-anchor" href="#_5-1-messagefilter-先保证-tf-可用" aria-label="Permalink to &quot;5.1 MessageFilter 先保证 TF 可用&quot;">​</a></h3><p>LaserScan 或 PointCloud2 不是一收到就立即写栅格。订阅器先经过 <code>tf2_ros::MessageFilter</code>，等待数据能够转换到 Costmap 的 <code>global_frame</code>。</p><p>如果 TF 缺失、时间戳超出 Buffer 或消息队列溢出，这帧数据不会进入障碍处理。此时 Topic 有频率，也不等于 Costmap 收到了有效观测。</p><p>LaserScan 会投影成 PointCloud2，再交给对应 <code>ObservationBuffer</code>。</p><h3 id="_5-2-observationbuffer-保存统一观测" tabindex="-1">5.2 ObservationBuffer 保存统一观测 <a class="header-anchor" href="#_5-2-observationbuffer-保存统一观测" aria-label="Permalink to &quot;5.2 ObservationBuffer 保存统一观测&quot;">​</a></h3><p>Buffer 保存：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传感器原点</span></span>
<span class="line"><span>已转换点云</span></span>
<span class="line"><span>obstacle_min／max_range</span></span>
<span class="line"><span>raytrace_min／max_range</span></span>
<span class="line"><span>observation_persistence</span></span>
<span class="line"><span>expected_update_rate</span></span></code></pre></div><p><code>observation_persistence</code> 控制观测保留多久；<code>expected_update_rate</code> 用来判断数据是否仍 current。它们不是同一个参数。</p><h3 id="_5-3-clearing-沿射线清出自由空间" tabindex="-1">5.3 Clearing：沿射线清出自由空间 <a class="header-anchor" href="#_5-3-clearing-沿射线清出自由空间" aria-label="Permalink to &quot;5.3 Clearing：沿射线清出自由空间&quot;">​</a></h3><p>配置 <code>clearing: true</code> 的观测，会从传感器原点向每个端点执行 raytrace，把射线经过的旧障碍栅格清为 FREE_SPACE。</p><p>清除距离由 <code>raytrace_min_range</code> 和 <code>raytrace_max_range</code> 控制。</p><p>这解释了动态障碍消失后的清理机制：不是“没有新点就自动消失”，而是新的传感器射线明确告诉系统这段空间现在为空。</p><h3 id="_5-4-marking-把命中点写成致命障碍" tabindex="-1">5.4 Marking：把命中点写成致命障碍 <a class="header-anchor" href="#_5-4-marking-把命中点写成致命障碍" aria-label="Permalink to &quot;5.4 Marking：把命中点写成致命障碍&quot;">​</a></h3><p>配置 <code>marking: true</code> 的观测经过高度、地图边界和 obstacle range 过滤。有效命中栅格写为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LETHAL_OBSTACLE = 254</span></span></code></pre></div><p><code>obstacle_max_range</code> 控制障碍标记距离，<code>raytrace_max_range</code> 控制自由空间清除距离。常见配置让 raytrace 稍远于 obstacle range，以便清除障碍边缘后的旧数据。</p><h3 id="_5-5-footprint-clearing" tabindex="-1">5.5 Footprint Clearing <a class="header-anchor" href="#_5-5-footprint-clearing" aria-label="Permalink to &quot;5.5 Footprint Clearing&quot;">​</a></h3><p>ObstacleLayer 默认可清空机器人 Footprint 内部的栅格，避免传感器看到机器人自身结构后把底盘内部标成障碍物。</p><p>这不是忽略 Footprint 周围障碍，只是把变换后的机器人多边形内部设为 FREE_SPACE。</p><h2 id="六、voxellayer-与-obstaclelayer-的区别" tabindex="-1">六、VoxelLayer 与 ObstacleLayer 的区别 <a class="header-anchor" href="#六、voxellayer-与-obstaclelayer-的区别" aria-label="Permalink to &quot;六、VoxelLayer 与 ObstacleLayer 的区别&quot;">​</a></h2><p>ObstacleLayer 直接在二维栅格上维护障碍。VoxelLayer 额外维护三维体素结构，按 z 方向累计 mark 与 clear，再把结果投影到二维 Master Costmap。</p><p>两者都消费 LaserScan 或 PointCloud2，也都使用 ObservationBuffer，但 VoxelLayer 更适合需要高度维度过滤或多层点云占用的场景。</p><p>最终 Planner 和 Controller 仍消费二维 Master Costmap，不直接读取体素网格。</p><h2 id="七、一次-updatemap-为什么分两阶段" tabindex="-1">七、一次 <code>updateMap()</code> 为什么分两阶段 <a class="header-anchor" href="#七、一次-updatemap-为什么分两阶段" aria-label="Permalink to &quot;七、一次 \`updateMap()\` 为什么分两阶段&quot;">​</a></h2><p>每轮融合都持有 Master Costmap mutex，避免 VoxelLayer 等非线程安全更新与外部读取交叉。</p><p><img src="`+r+`" alt="图 4：updateBounds 与 updateCosts 两阶段融合"></p><h3 id="_7-1-updatebounds" tabindex="-1">7.1 <code>updateBounds()</code> <a class="header-anchor" href="#_7-1-updatebounds" aria-label="Permalink to &quot;7.1 \`updateBounds()\`&quot;">​</a></h3><p>所有插件和 Filter 按配置顺序执行：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">updateBounds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(robot_x, robot_y, robot_yaw,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">             &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">min_x, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">min_y, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_x, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_y);</span></span></code></pre></div><p>这一阶段主要做两件事。</p><h4 id="_7-1-1-更新各层私有状态" tabindex="-1">7.1.1 更新各层私有状态 <a class="header-anchor" href="#_7-1-1-更新各层私有状态" aria-label="Permalink to &quot;7.1.1 更新各层私有状态&quot;">​</a></h4><p>读取各层最新缓存，更新各层私有状态。</p><h4 id="_7-1-2-合并公共更新边界" tabindex="-1">7.1.2 合并公共更新边界 <a class="header-anchor" href="#_7-1-2-合并公共更新边界" aria-label="Permalink to &quot;7.1.2 合并公共更新边界&quot;">​</a></h4><p>把本轮可能发生变化的世界坐标范围并入公共边界。</p><p>边界只能扩大，不能缩小前一层已经声明的范围。源码会检测非法缩小并指出具体 Layer 或 Filter。</p><p>合并后的世界坐标再通过 <code>worldToMapEnforceBounds()</code> 转成并裁剪为栅格窗口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x0 ～ xn</span></span>
<span class="line"><span>y0 ～ yn</span></span></code></pre></div><p>这样大地图上只有变化区域需要重算和发布，而不是每周期全图处理。</p><h3 id="_7-2-updatecosts" tabindex="-1">7.2 <code>updateCosts()</code> <a class="header-anchor" href="#_7-2-updatecosts" aria-label="Permalink to &quot;7.2 \`updateCosts()\`&quot;">​</a></h3><p>没有 Filter 时，系统清空 <code>combined_costmap_</code> 的更新窗口，再依次让每个插件写入。</p><p>存在 Filter 时，按以下步骤处理。</p><h4 id="_7-2-1-写入-primary-costmap" tabindex="-1">7.2.1 写入 Primary Costmap <a class="header-anchor" href="#_7-2-1-写入-primary-costmap" aria-label="Permalink to &quot;7.2.1 写入 Primary Costmap&quot;">​</a></h4><p>插件写入 <code>primary_costmap_</code>。</p><h4 id="_7-2-2-复制-combined-costmap-更新窗口" tabindex="-1">7.2.2 复制 Combined Costmap 更新窗口 <a class="header-anchor" href="#_7-2-2-复制-combined-costmap-更新窗口" aria-label="Permalink to &quot;7.2.2 复制 Combined Costmap 更新窗口&quot;">​</a></h4><p>把更新窗口复制到 <code>combined_costmap_</code>。</p><h4 id="_7-2-3-执行-filter-后处理" tabindex="-1">7.2.3 执行 Filter 后处理 <a class="header-anchor" href="#_7-2-3-执行-filter-后处理" aria-label="Permalink to &quot;7.2.3 执行 Filter 后处理&quot;">​</a></h4><p>Filter 依次后处理 <code>combined_costmap_</code>。</p><p>这个双缓冲设计防止 Keepout 或 Speed Filter 的结果反过来成为下一轮基础插件的输入。基础环境代价保存在 primary，语义约束只作用于最终 combined 输出。</p><h2 id="八、插件顺序为什么会改变结果" tabindex="-1">八、插件顺序为什么会改变结果 <a class="header-anchor" href="#八、插件顺序为什么会改变结果" aria-label="Permalink to &quot;八、插件顺序为什么会改变结果&quot;">​</a></h2><p>Layer 不是简单求和。每个插件自己选择组合方法：覆盖、真覆盖、取最大值或不写入。</p><p>例如默认顺序：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>StaticLayer</span></span>
<span class="line"><span>→ ObstacleLayer</span></span>
<span class="line"><span>→ InflationLayer</span></span></code></pre></div><p>Static 先提供墙体，Obstacle 再加入动态致命障碍，Inflation 最后扫描当前 Master 中的致命种子并生成梯度。</p><p>如果 Inflation 放在 Obstacle 前面，本轮新标记的动态障碍可能来不及参与相同期望顺序的膨胀。自定义 Layer 插入位置也会改变它看到的上游代价。</p><p>因此排障必须同时核对 <code>plugins</code> 数组顺序和每个 <code>&lt;plugin_name&gt;.plugin</code> 类型，不能只确认动态库成功加载。</p><h2 id="九、footprint-怎样影响代价安全边界" tabindex="-1">九、Footprint 怎样影响代价安全边界 <a class="header-anchor" href="#九、footprint-怎样影响代价安全边界" aria-label="Permalink to &quot;九、Footprint 怎样影响代价安全边界&quot;">​</a></h2><p>机器人几何来自两条互斥配置路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>footprint 有效 → 使用多边形</span></span>
<span class="line"><span>footprint 为空或无效 → 使用 robot_radius 生成近似圆</span></span></code></pre></div><p><img src="`+c+`" alt="图 5：Footprint、内切半径与 Inflation"></p><p><code>footprint_padding</code> 会扩张基础几何。<code>LayeredCostmap::setFootprint()</code> 保存 padded footprint，并计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inscribed_radius     机器人中心到边界的最短距离</span></span>
<span class="line"><span>circumscribed_radius 机器人中心到边界的最长距离</span></span></code></pre></div><p>随后通知所有 Layer 和 Filter 执行 <code>onFootprintChanged()</code>。</p><p>Costmap2DROS 还订阅 <code>footprint</code> Topic，运行中收到新 Polygon 时会重新计算上述数据，并通过 <code>published_footprint</code> 发布机器人当前位姿下的定向多边形。</p><h2 id="十、inflation-layer-怎样生成安全梯度" tabindex="-1">十、Inflation Layer 怎样生成安全梯度 <a class="header-anchor" href="#十、inflation-layer-怎样生成安全梯度" aria-label="Permalink to &quot;十、Inflation Layer 怎样生成安全梯度&quot;">​</a></h2><p>Inflation 不是把障碍物尺寸简单放大一圈，而是根据到最近障碍的距离赋值。</p><p>它把 <code>LETHAL_OBSTACLE</code>，以及可选的 unknown 栅格，作为距离为 0 的种子；按距离桶从近到远扩散到相邻栅格。</p><p>关键参数是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inflation_radius</span></span>
<span class="line"><span>cost_scaling_factor</span></span>
<span class="line"><span>inflate_unknown</span></span>
<span class="line"><span>inflate_around_unknown</span></span></code></pre></div><p>成本语义大致为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>障碍物本体                         254</span></span>
<span class="line"><span>Footprint 内切半径以内              253</span></span>
<span class="line"><span>内切半径外、inflation_radius 内     指数衰减</span></span>
<span class="line"><span>膨胀半径以外                       保留原代价</span></span></code></pre></div><p><code>cost_scaling_factor</code> 越大，代价衰减越快；它不是“越大越保守”。<code>inflation_radius</code> 才决定梯度传播到多远。</p><p>当 Footprint 变化时 Inflation 会重建缓存并触发全区域重新膨胀。如果 <code>inflation_radius</code> 小于 <code>inscribed_radius</code>，代码会明确报错，因为此时膨胀范围连机器人自身内切半径都覆盖不了。</p><h2 id="十一、滚动窗口如何跟着机器人移动" tabindex="-1">十一、滚动窗口如何跟着机器人移动 <a class="header-anchor" href="#十一、滚动窗口如何跟着机器人移动" aria-label="Permalink to &quot;十一、滚动窗口如何跟着机器人移动&quot;">​</a></h2><p>Local Costmap 常配置 <code>rolling_window: true</code>。</p><p>每轮 <code>LayeredCostmap::updateMap()</code> 根据机器人位姿把原点更新为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>origin_x = robot_x - size_x_meters / 2</span></span>
<span class="line"><span>origin_y = robot_y - size_y_meters / 2</span></span></code></pre></div><p><code>Costmap2D::updateOrigin()</code> 不会无脑清空整张图。它计算新旧窗口重叠区域，把仍有效的旧数据复制到新位置，新增区域再用默认值初始化。</p><p>因此滚动窗口是在固定大小内移动栅格坐标原点，不是创建无限增长地图。</p><p>Global Costmap 通常关闭 rolling window，让 StaticLayer 的地图尺寸、分辨率和原点决定全局范围；Local Costmap 通常围绕机器人保持较小窗口，用高频传感器数据服务控制器。</p><h2 id="十二、costmap-filter-为什么独立于普通-layer" tabindex="-1">十二、Costmap Filter 为什么独立于普通 Layer <a class="header-anchor" href="#十二、costmap-filter-为什么独立于普通-layer" aria-label="Permalink to &quot;十二、Costmap Filter 为什么独立于普通 Layer&quot;">​</a></h2><p>Filter 也实现 Layer 接口，但它们表达的是语义规则，不是基础环境观测。</p><p>典型 Filter 包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KeepoutFilter  禁止进入区域</span></span>
<span class="line"><span>SpeedFilter    限速区域</span></span>
<span class="line"><span>BinaryFilter   基于掩码开关某种二值行为</span></span></code></pre></div><p>它们通常订阅两类数据：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filter_mask OccupancyGrid</span></span>
<span class="line"><span>CostmapFilterInfo：type、mask topic、base、multiplier</span></span></code></pre></div><p>Filter 在普通插件完成后处理 <code>combined_costmap_</code>。Clear Costmap 服务不会清理 Filter，因为过滤规则应该持续存在，不能因一次恢复动作而丢失禁行区或限速区。</p><h2 id="十三、costmap-怎样发布给外部" tabindex="-1">十三、Costmap 怎样发布给外部 <a class="header-anchor" href="#十三、costmap-怎样发布给外部" aria-label="Permalink to &quot;十三、Costmap 怎样发布给外部&quot;">​</a></h2><p>Costmap2DPublisher 提供三条 Topic 和一个服务。</p><p><img src="`+d+`" alt="图 6：发布、查询、清理和下游消费"></p><h3 id="_13-1-costmap" tabindex="-1">13.1 <code>costmap</code> <a class="header-anchor" href="#_13-1-costmap" aria-label="Permalink to &quot;13.1 \`costmap\`&quot;">​</a></h3><p>这是 <code>nav_msgs/msg/OccupancyGrid</code>。内部 0～255 被翻译为 -1～100：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0   → 0</span></span>
<span class="line"><span>253 → 99</span></span>
<span class="line"><span>254 → 100</span></span>
<span class="line"><span>255 → -1</span></span>
<span class="line"><span>1～252 → 1～98 线性缩放</span></span></code></pre></div><p>它适合 RViz2 和通用 OccupancyGrid 工具，但不能无损保留全部内部代价等级。</p><h3 id="_13-2-costmap-raw" tabindex="-1">13.2 <code>costmap_raw</code> <a class="header-anchor" href="#_13-2-costmap-raw" aria-label="Permalink to &quot;13.2 \`costmap_raw\`&quot;">​</a></h3><p>这是 <code>nav2_msgs/msg/Costmap</code>，保留内部 0～255 数据和 Master metadata，适合 Nav2 工具与精确代价分析。</p><h3 id="_13-3-costmap-updates" tabindex="-1">13.3 <code>costmap_updates</code> <a class="header-anchor" href="#_13-3-costmap-updates" aria-label="Permalink to &quot;13.3 \`costmap_updates\`&quot;">​</a></h3><p>当尺寸、分辨率和原点没有变化，且 <code>always_send_full_costmap=false</code> 时，可只发布本轮更新窗口的 <code>map_msgs/msg/OccupancyGridUpdate</code>。</p><p>如果滚动窗口导致 origin 变化，或地图尺寸／分辨率变化，则必须重新发布完整 Costmap。</p><p>这三类 Publisher 都使用 transient local 和 reliable。实际准备与发布还会检查订阅者数量，避免没有消费者时重复序列化大数组。</p><h3 id="_13-4-get-costmap" tabindex="-1">13.4 <code>get_costmap</code> <a class="header-anchor" href="#_13-4-get-costmap" aria-label="Permalink to &quot;13.4 \`get_costmap\`&quot;">​</a></h3><p>GetCostmap Service 返回完整 Raw Costmap 快照，适合按需查询。</p><h2 id="十四、planner-和-controller-是否通过-topic-读取-costmap" tabindex="-1">十四、Planner 和 Controller 是否通过 Topic 读取 Costmap <a class="header-anchor" href="#十四、planner-和-controller-是否通过-topic-读取-costmap" aria-label="Permalink to &quot;十四、Planner 和 Controller 是否通过 Topic 读取 Costmap&quot;">​</a></h2><p>通常不是。</p><p>Planner Server 和 Controller Server 内部持有各自的 <code>Costmap2DROS</code>，算法插件通过指针取得 Master Costmap，并在需要时锁 mutex 直接读取。</p><p>Topic 主要用于可视化、跨节点工具和调试。把 <code>publish_frequency</code> 调高不会让同进程 Planner 更快得到内部更新；真正影响算法新鲜度的是 <code>update_frequency</code>、传感器到达、TF 和 Layer current 状态。</p><h2 id="十五、footprint-collision-checker-检查了什么" tabindex="-1">十五、Footprint Collision Checker 检查了什么 <a class="header-anchor" href="#十五、footprint-collision-checker-检查了什么" aria-label="Permalink to &quot;十五、Footprint Collision Checker 检查了什么&quot;">​</a></h2><p><code>FootprintCollisionChecker</code> 把基础 Footprint 变换到候选 x、y、theta，使用 worldToMap 定位各顶点，再沿多边形边界进行栅格线遍历，返回边界上的最大代价。</p><p>如果 Footprint 顶点越出 Costmap，返回 LETHAL_OBSTACLE。</p><p>这个检查重点是多边形边界，不是对内部每个栅格做完整填充扫描。通常配合已经膨胀的 Costmap 使用，借助 Inflation 把机器人实体尺寸编码进周围梯度。</p><h2 id="十六、三类清图服务究竟清什么" tabindex="-1">十六、三类清图服务究竟清什么 <a class="header-anchor" href="#十六、三类清图服务究竟清什么" aria-label="Permalink to &quot;十六、三类清图服务究竟清什么&quot;">​</a></h2><p>每个 Costmap2DROS 创建：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clear_entirely_&lt;costmap_name&gt;</span></span>
<span class="line"><span>clear_around_&lt;costmap_name&gt;</span></span>
<span class="line"><span>clear_except_&lt;costmap_name&gt;</span></span></code></pre></div><p><code>clear_around</code> 清理以机器人为中心的方形区域；<code>clear_except</code> 保留中心方形区域、清理外部；<code>clear_entirely</code> 调用 resetLayers 重置全部可重置插件。</p><p>区域清理只遍历普通 plugins 中 <code>isClearable()</code> 为 true 的 CostmapLayer。Filter 不参与清理。</p><p>清理后 Layer 会添加 extra bounds，迫使下一轮更新覆盖相关区域。否则数组虽被清空，增量融合和发布可能不知道哪些位置已经变化。</p><p>清图不是永久删除静态地图和当前可见障碍。下一轮 StaticLayer、ObstacleLayer 仍会根据现有输入重新写回有效代价。</p><h2 id="十七、iscurrent-为什么重要" tabindex="-1">十七、<code>isCurrent()</code> 为什么重要 <a class="header-anchor" href="#十七、iscurrent-为什么重要" aria-label="Permalink to &quot;十七、\`isCurrent()\` 为什么重要&quot;">​</a></h2><p>LayeredCostmap 的 current 状态是所有已启用 Layer 和 Filter current 状态的逻辑与。</p><p>ObstacleLayer 根据 ObservationBuffer 的 <code>expected_update_rate</code> 判断传感器是否过期；StaticLayer 在收到并处理地图后才 current；Filter 也可以维护自己的新鲜度。</p><p>Costmap initialized 只表示至少完成了一次融合，current 则表示当前依赖数据没有被判定为过期。两者不能互换。</p><p>Controller Server 常要求 Costmap current，防止使用长时间未更新的障碍数据继续输出速度。</p><h2 id="十八、最常见的九个排障边界" tabindex="-1">十八、最常见的九个排障边界 <a class="header-anchor" href="#十八、最常见的九个排障边界" aria-label="Permalink to &quot;十八、最常见的九个排障边界&quot;">​</a></h2><h3 id="_18-1-topic-有消息不等于-layer-收到有效数据" tabindex="-1">18.1 Topic 有消息不等于 Layer 收到有效数据 <a class="header-anchor" href="#_18-1-topic-有消息不等于-layer-收到有效数据" aria-label="Permalink to &quot;18.1 Topic 有消息不等于 Layer 收到有效数据&quot;">​</a></h3><p>MessageFilter 还需要对应时间戳的 TF。</p><h3 id="_18-2-标记与清除距离必须分别配置" tabindex="-1">18.2 标记与清除距离必须分别配置 <a class="header-anchor" href="#_18-2-标记与清除距离必须分别配置" aria-label="Permalink to &quot;18.2 标记与清除距离必须分别配置&quot;">​</a></h3><p><code>obstacle_max_range</code> 控制标记，<code>raytrace_max_range</code> 控制清除，不能只改一个。</p><h3 id="_18-3-数据保留与新鲜度不是同一参数" tabindex="-1">18.3 数据保留与新鲜度不是同一参数 <a class="header-anchor" href="#_18-3-数据保留与新鲜度不是同一参数" aria-label="Permalink to &quot;18.3 数据保留与新鲜度不是同一参数&quot;">​</a></h3><p><code>observation_persistence</code> 是数据保留时间，<code>expected_update_rate</code> 是新鲜度判断，不是同一作用。</p><h3 id="_18-4-更新频率不等于发布频率" tabindex="-1">18.4 更新频率不等于发布频率 <a class="header-anchor" href="#_18-4-更新频率不等于发布频率" aria-label="Permalink to &quot;18.4 更新频率不等于发布频率&quot;">​</a></h3><p>Planner／Controller 内部读取与 RViz2 Topic 显示可能不同步。</p><h3 id="_18-5-插件数组顺序会改变融合结果" tabindex="-1">18.5 插件数组顺序会改变融合结果 <a class="header-anchor" href="#_18-5-插件数组顺序会改变融合结果" aria-label="Permalink to &quot;18.5 插件数组顺序会改变融合结果&quot;">​</a></h3><p>尤其要核对 Inflation 与自定义 Layer 的相对位置。</p><h3 id="_18-6-联合检查-footprint、padding-和-inflation" tabindex="-1">18.6 联合检查 Footprint、Padding 和 Inflation <a class="header-anchor" href="#_18-6-联合检查-footprint、padding-和-inflation" aria-label="Permalink to &quot;18.6 联合检查 Footprint、Padding 和 Inflation&quot;">​</a></h3><p>只增大 <code>robot_radius</code> 不一定影响已经显式配置的 polygon footprint。</p><h3 id="_18-7-两张-costmap-不一定使用相同坐标系" tabindex="-1">18.7 两张 Costmap 不一定使用相同坐标系 <a class="header-anchor" href="#_18-7-两张-costmap-不一定使用相同坐标系" aria-label="Permalink to &quot;18.7 两张 Costmap 不一定使用相同坐标系&quot;">​</a></h3><p>Local Costmap 的 global frame 常为 <code>odom</code>，Global Costmap 常为 <code>map</code>。不能假设两张图使用同一坐标系或同一原点。</p><h3 id="_18-8-clear-服务不会永久移除持续规则" tabindex="-1">18.8 Clear 服务不会永久移除持续规则 <a class="header-anchor" href="#_18-8-clear-服务不会永久移除持续规则" aria-label="Permalink to &quot;18.8 Clear 服务不会永久移除持续规则&quot;">​</a></h3><p>Clear 服务只清理可清理 Layer，Filter 和持续输入会在下一轮重新施加规则。</p><h3 id="_18-9-rviz2-costmap-不是内部原始代价" tabindex="-1">18.9 RViz2 Costmap 不是内部原始代价 <a class="header-anchor" href="#_18-9-rviz2-costmap-不是内部原始代价" aria-label="Permalink to &quot;18.9 RViz2 Costmap 不是内部原始代价&quot;">​</a></h3><p>RViz2 显示的是转换后的 OccupancyGrid，不是内部原始 0～255 Costmap；精确分析应查看 <code>costmap_raw</code> 或直接查询 Master。</p><h2 id="十九、建议的观测顺序" tabindex="-1">十九、建议的观测顺序 <a class="header-anchor" href="#十九、建议的观测顺序" aria-label="Permalink to &quot;十九、建议的观测顺序&quot;">​</a></h2><h3 id="_19-1-检查-costmap-lifecycle" tabindex="-1">19.1 检查 Costmap Lifecycle <a class="header-anchor" href="#_19-1-检查-costmap-lifecycle" aria-label="Permalink to &quot;19.1 检查 Costmap Lifecycle&quot;">​</a></h3><p>确认 Costmap Lifecycle 是否 active。</p><h3 id="_19-2-检查机器人位姿-tf" tabindex="-1">19.2 检查机器人位姿 TF <a class="header-anchor" href="#_19-2-检查机器人位姿-tf" aria-label="Permalink to &quot;19.2 检查机器人位姿 TF&quot;">​</a></h3><p>确认 <code>global_frame ← robot_base_frame</code> TF 是否可用。</p><h3 id="_19-3-检查插件配置" tabindex="-1">19.3 检查插件配置 <a class="header-anchor" href="#_19-3-检查插件配置" aria-label="Permalink to &quot;19.3 检查插件配置&quot;">​</a></h3><p>确认 <code>plugins／filters</code> 名称、类型和顺序是否正确。</p><h3 id="_19-4-检查-staticlayer" tabindex="-1">19.4 检查 StaticLayer <a class="header-anchor" href="#_19-4-检查-staticlayer" aria-label="Permalink to &quot;19.4 检查 StaticLayer&quot;">​</a></h3><p>确认 StaticLayer 是否收到 <code>/map</code>，QoS 和 frame 是否匹配。</p><h3 id="_19-5-检查传感器-messagefilter" tabindex="-1">19.5 检查传感器 MessageFilter <a class="header-anchor" href="#_19-5-检查传感器-messagefilter" aria-label="Permalink to &quot;19.5 检查传感器 MessageFilter&quot;">​</a></h3><p>确认传感器 MessageFilter 是否因 TF 丢弃消息。</p><h3 id="_19-6-检查-observationbuffer" tabindex="-1">19.6 检查 ObservationBuffer <a class="header-anchor" href="#_19-6-检查-observationbuffer" aria-label="Permalink to &quot;19.6 检查 ObservationBuffer&quot;">​</a></h3><p>确认 ObservationBuffer 是否 current。</p><h3 id="_19-7-检查更新线程" tabindex="-1">19.7 检查更新线程 <a class="header-anchor" href="#_19-7-检查更新线程" aria-label="Permalink to &quot;19.7 检查更新线程&quot;">​</a></h3><p>确认 <code>update_frequency</code> 是否大于 0，更新线程是否运行。</p><h3 id="_19-8-检查机器人安全边界参数" tabindex="-1">19.8 检查机器人安全边界参数 <a class="header-anchor" href="#_19-8-检查机器人安全边界参数" aria-label="Permalink to &quot;19.8 检查机器人安全边界参数&quot;">​</a></h3><p>确认 Footprint、padding、<code>inflation_radius</code> 是否一致。</p><h3 id="_19-9-对比内部与外部-costmap" tabindex="-1">19.9 对比内部与外部 Costmap <a class="header-anchor" href="#_19-9-对比内部与外部-costmap" aria-label="Permalink to &quot;19.9 对比内部与外部 Costmap&quot;">​</a></h3><p>确认内部 Master、<code>costmap_raw</code> 与 RViz2 costmap 是否一致。</p><h3 id="_19-10-检查清图后的数据回写" tabindex="-1">19.10 检查清图后的数据回写 <a class="header-anchor" href="#_19-10-检查清图后的数据回写" aria-label="Permalink to &quot;19.10 检查清图后的数据回写&quot;">​</a></h3><p>确认 Clear 服务后相关 Layer 是否被持续输入重新写回。</p><h2 id="二十、结语" tabindex="-1">二十、结语 <a class="header-anchor" href="#二十、结语" aria-label="Permalink to &quot;二十、结语&quot;">​</a></h2><p><code>nav2_costmap_2d</code> 的完整主链可以压缩成四次转换：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地图／传感器／TF</span></span>
<span class="line"><span>→ 各插件私有状态</span></span>
<span class="line"><span>→ 更新窗口内按顺序融合</span></span>
<span class="line"><span>→ 与机器人尺寸相关的最终 Master Costmap</span></span></code></pre></div><p>再由 Master Costmap 分出三条用途：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同进程直接读取 → Planner／Controller／碰撞检查</span></span>
<span class="line"><span>转换发布         → RViz2／跨节点工具</span></span>
<span class="line"><span>服务修改         → 查询与恢复清图</span></span></code></pre></div><p>理解更新窗口、插件顺序、Footprint 和 Inflation 这四个核心点后，Costmap 就不再是一张颜色复杂的图，而是一套能够解释每一个障碍来源、每一个代价值和每一次更新时机的导航安全数据流。</p>`,232)])])}const k=e(h,[["render",u]]);export{y as __pageData,k as default};
